import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const receiptFile = 'expo-push.json';
const url = 'https://rh2.example/console/rooms/standup';
// the World's doors are the twin's own, at the URL the World names for it
const twin = process.env.EXPO_TWIN_URL;
if (!twin) throw new Error('The World names no Expo twin URL.');
if (process.argv[2] === 'readback') {
  // what each phone shows (the World's inbox door stands in for the phone's notification centre)
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const shown = [];
  for (const token of saved.tokens) {
    const response = await fetch(twin + '/_twin/devices/' + encodeURIComponent(token) + '/notifications');
    assert.equal(response.status, 200);
    const { data } = await response.json();
    assert.equal(data.length, 1, 'the phone shows the one notification it was sent');
    assert.equal(data[0].title, 'Ada replied in Standup');
    assert.equal(data[0].body, 'The staging credentials are in the vault.');
    assert.equal(data[0].data.url, url);
    assert.equal(data[0].to, token);
    assert.ok(data[0].received_at, 'the phone was handed it');
    shown.push({ token, id: data[0].id, received_at: data[0].received_at });
  }
  console.log(JSON.stringify({ retained: true, shown }));
} else {
  // Bruno's phones install RH2's mobile app and register for pushes (expo-notifications on the phone; the World's devices door)
  const tokens = [];
  for (const platform of ['ios', 'android']) {
    const response = await fetch(twin + '/_twin/devices', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ project: '@runhuman/rh2-mobile', platform, owner: 'bruno' }) });
    if (response.status !== 201) throw new Error('The phone could not register: ' + response.status + ' ' + await response.text());
    tokens.push((await response.json()).token);
  }
  // RH2's away notifier (apps/rh2/src/notify/away.ts, sendToDevices): one message per phone, as it sends them
  const title = 'Ada replied in Standup';
  const body = 'The staging credentials are in the vault.';
  const response = await fetch('https://exp.host/--/api/v2/push/send', {
    body: JSON.stringify(tokens.map((to) => ({ body: body.slice(0, 1000), data: { url }, sound: 'default', title, to }))),
    headers: { accept: 'application/json', 'content-type': 'application/json' },
    method: 'POST',
    signal: AbortSignal.timeout(10_000),
  });
  const answer = await response.json();
  assert.equal(response.status, 200, JSON.stringify(answer));
  assert.ok(Array.isArray(answer.data), 'the push service answers its tickets as data');
  assert.equal(answer.data.length, tokens.length, 'one ticket per message, in order');
  for (const ticket of answer.data) {
    assert.equal(ticket.status, 'ok', JSON.stringify(ticket));
    assert.match(ticket.id, /^[0-9a-f-]{36}$/, 'an ok ticket names its receipt id');
  }
  writeFileSync(receiptFile, JSON.stringify({ tokens, tickets: answer.data.map((t) => t.id) }) + '\n');
  console.log(JSON.stringify({ sent: answer.data.length, tickets: answer.data }));
}
